// SOAL: Analisis fungsi berikut dengan White Box Testing
function hitungBonus(penjualan, rating) {
  let bonus = 0;

  if (penjualan >= 10_000_000) {    // Keputusan 1 (D1)
    bonus += 500_000;
  }

  if (rating >= 4.5) {              // Keputusan 2 (D2)
    bonus += 250_000;
  } else if (rating >= 3.5) {      // Keputusan 3 (D3)
    bonus += 100_000;
  }

  return bonus;
}

// JAWABAN:

// LANGKAH 1: Hitung Cyclomatic Complexity
// Jumlah Keputusan (D1, D2, D3) = 3
// V(G) = 3 + 1 = 4
// → Minimal 4 test case dibutuhkan

// LANGKAH 2: Identifikasi 4 Independent Path
// Path 1: D1=false, D2=false, D3=false → bonus = 0
// Path 2: D1=true,  D2=false, D3=false → bonus = 500.000
// Path 3: D1=false, D2=true             → bonus = 250.000
// Path 4: D1=false, D2=false, D3=true  → bonus = 100.000

// LANGKAH 3: Buat Test Case
const testCases = [
  { id:'TC1', penjualan: 5_000_000, rating: 3.0, expected: 0,       path: 'P1' },
  { id:'TC2', penjualan: 15_000_000, rating: 3.0, expected: 500_000, path: 'P2' },
  { id:'TC3', penjualan: 5_000_000, rating: 4.8, expected: 250_000, path: 'P3' },
  { id:'TC4', penjualan: 5_000_000, rating: 4.0, expected: 100_000, path: 'P4' },
];
